const $=s=>document.querySelector(s),A='assets/';
// === MASCOT IMAGES: change file names here to swap pictures everywhere ===
const MASCOT={thumbs:A+'mascot_thumbs.png',lab:A+'mascot_lab.png'};
const LV=[['Beginner',0],['Explorer',200],['Scholar',500],['Expert',900],['Master',1400]];
const S={tab:'home',v:'home',xp:120,lessons:6,quizzes:0,streak:6,daily:false,lessonDone:false,lp:0,q:0,sel:null,sub:false,score:0,badges:['lesson'],acts:['Completed "Bilangan Bulat"','Quiz Pecahan: 80%']};
const SUBJ=[['Mathematics','math',C.pink,K,'Numbers, algebra and shapes',24,40],['Physics','physics',C.pur,'#fff','Planets, energy and forces',12,32],['Chemistry','chem',C.tur,K,'Molecules and reactions',8,28],['Biology','bio',C.lime,K,'Plants, cells and nature',15,30],['English','eng',C.yel,K,'Words, grammar and stories',20,36],['Indonesian','indo',C.mag,'#fff','Teks, tata bahasa, sastra',18,30],['History','hist','#FF8A5B',K,'Events that shaped the world',10,24],['Geography','geo','#5CC8FF',K,'Maps, climate and regions',14,26]];
const BADGES=[['lesson','book','First Lesson',C.pink],['quiz','bolt','First Quiz',C.tur],['perfect','star','Perfect Score',C.yel],['streak','flame','7-Day Streak',C.mag],['mastery','trophy','Subject Mastery',C.lime],['consist','check','Consistency',C.pur]];
ART.book=ART.indo;
const LESSON=[['Concept','A <b>linear equation</b> has a variable with power 1, like <b>2x + 3 = 11</b>. Solving it means finding the x that makes both sides equal.','Do the same operation on both sides to keep the equation balanced.','2x + 3 = 11 → 2x = 8 → x = 4'],['Steps','1) Move constants to the right side. 2) Divide by the coefficient of x. 3) Check by putting x back in.','Always check your answer by substituting x back.','x − 5 = 9 → x = 14'],['Practice idea','Word problems: "Twice a number plus 3 equals 11." Turn the words into 2x + 3 = 11.','Underline keywords: twice, plus, equals.','3x = 12 → x = 4']];
const QZ=[['What is x in 2x + 3 = 11?',['x = 3','x = 4','x = 7','x = 14'],1,'Subtract 3: 2x = 8, then divide by 2: x = 4.'],['Solve: x − 5 = 9',['x = 4','x = 9','x = 14','x = 45'],2,'Add 5 to both sides: x = 14.'],['If 3x = 12, then x + 1 =',['4','5','13','36'],1,'x = 4, so x + 1 = 5.']];
const lvl=()=>{let i=0;LV.forEach((l,k)=>{if(S.xp>=l[1])i=k});const n=LV[i+1];return{i,name:LV[i][0],next:n?n[0]:'Max',pct:n?(S.xp-LV[i][1])/(n[1]-LV[i][1])*100:100}};
const prog=()=>Math.min(100,Math.round(30+S.lessons*1.2+S.quizzes*4));
const bar=(p,c)=>`<div class="bar" style="${c?'--c:'+c:''}"><i style="width:${Math.max(4,p)}%"></i></div>`;
const sart=(n,col,s=96,cls)=>svgw(subF(n,col),s,cls);
const deco=()=>svgw(frag('blob','#E9FFFD'),300,'deco').replace('<svg','<svg style="top:-60px;right:-90px"')+svgw(frag('blob',C.tur+'55'),170,'deco').replace('<svg','<svg style="top:520px;left:-70px"');
function toast(m,t){const e=$('#toast');e.innerHTML=ico(t=='err'?'cross':'check',30,t=='err'?C.mag:C.lime)+'<span>'+m+'</span>';e.style.borderColor=t=='err'?'#A90B70':'#48E6C6';e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2500)}
function gain(n,why){S.xp+=n;const e=document.createElement('div');e.className='xp';e.innerHTML=svgw(frag('burst',C.lime),130)+'<span>+'+n+' XP</span>';$('#app').append(e);setTimeout(()=>e.remove(),1500);if(why)toast(why)}
function unlock(id){if(S.badges.includes(id))return;S.badges.push(id);const b=BADGES.find(x=>x[0]==id);setTimeout(()=>toast('Badge unlocked: <b>'+b[2]+'</b>'),1000)}
function go(tab,v){S.tab=tab;S.v=v||tab;render()}
const hero=()=>{const l=lvl();return`<div class="greet"><div class="ph">${svgw(frag('burst',C.yel),130)}<img class="mc" src="${MASCOT.thumbs}" alt="Mascot"></div><div><p class="sm" style="font-weight:600;color:var(--pur)">Welcome back</p><h1>Hai,<br>Yotsuba!</h1></div>${svgw(frag('bulb',C.yel,C.lime),54).replace('<svg','<svg style="position:absolute;right:0;top:-6px;transform:rotate(12deg)"')}</div>
<div class="card dark t1"><div class="row sp"><span class="pill y">${ico('star',20,C.yel,C.yel)} ${S.xp} XP</span><span class="pill">Level: ${l.name}</span></div><div style="margin:12px 0 6px">${bar(l.pct,C.lime)}</div><p class="sm">${Math.round(l.pct)}% to ${l.next}</p></div>`};
const subCard=(s,i,k)=>`<div class="card sc ${k%2?'t2':'t1'}" style="background:${s[2]};color:${s[3]}" onclick="openSubj(${i})">${sart(s[1],s[2],92)}<h3>${s[0]}</h3><p class="sm">${s[4]}</p>${bar(Math.round(s[5]/s[6]*100),s[3]=='#fff'?C.lime:C.mag)}<p class="sm"><b>${s[5]}/${s[6]}</b> lessons</p></div>`;
function openSubj(i){i==0?go('explore','subject'):toast('Prototype: only Mathematics is open','err')}
const head=(t,sub,art)=>`<div class="row sp" style="margin-bottom:10px"><div><h1>${t}</h1><p style="color:var(--pur)">${sub}</p></div>${art||''}</div>`;
const V={
home:()=>`<div class="pg">${deco()}${hero()}<div class="grid" style="grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:22px"><div class="card stat" style="background:#FFE3F1">${ico('flame',44,C.pink,C.yel)}<b>${S.streak}</b><span>Day streak</span></div><div class="card stat" style="background:#FFF4B8">${ico('trophy',44,C.yel,C.pink)}<b>${S.badges.length}</b><span>Badges</span></div><div class="card stat" style="background:#D9FFD0">${ico('bars',44,C.lime,C.tur)}<b>${prog()}%</b><span>Progress</span></div></div>
<div class="card dark t2" style="margin-top:6px;overflow:hidden"><div class="row"><div style="flex:1"><div class="row sp"><h3>Daily Challenge</h3><span class="pill y">+50 XP</span></div><p class="sm" style="margin:6px 0 10px">Finish 1 Math quiz today</p>${bar(S.daily?100:S.lessonDone?50:10,C.lime)}</div>${ico('robot',70,C.tur,C.yel)}</div><button class="btn" onclick="go('challenges')" ${S.daily?'disabled':''}>${S.daily?'Completed!':"Let's go!"}</button></div>
<h2>Continue learning</h2><div class="card row sc t1" style="min-height:0;flex-direction:row;justify-content:flex-start;background:var(--yel)" onclick="go('explore','subject')">${sart('math',C.pink,70).replace('<svg','<svg style="position:static"')}<div><h3>Basic Algebra</h3><p class="sm">${S.lessonDone?'Lesson done – take the quiz!':'Mathematics · Chapter 2'}</p></div></div>
<h2>Recommended</h2><div class="grid">${[0,3].map((i,k)=>subCard(SUBJ[i],i,k)).join('')}</div>
<h2>Latest sticker</h2><div class="card row t2">${stk(BADGES.find(b=>b[0]==S.badges.at(-1))[1],74,BADGES.find(b=>b[0]==S.badges.at(-1))[3],C.yel,'#fff')}<div><h3>${BADGES.find(b=>b[0]==S.badges.at(-1))[2]}</h3><p class="sm">Your newest achievement</p></div><img class="mc" src="${MASCOT.lab}" style="height:76px;margin-left:auto" alt=""></div></div>`,
explore:()=>`<div class="pg">${deco()}${head('Explore','Pick a subject and play!',ico('compass',64,C.tur,C.pink))}<div class="grid">${SUBJ.map((s,i)=>subCard(s,i,i)).join('')}</div></div>`,
subject:()=>{const ch=[['Bilangan Bulat',1],['Aljabar Dasar',S.lessonDone?1:0],['Persamaan Linear',S.lessonDone?2:-1]];return`<div class="pg">${deco()}<button class="btn sm ghost" onclick="go('explore')">← Back</button><div class="row sp" style="margin:12px 0"><div><h1>Mathematics</h1><p style="color:var(--pur)">Numbers, algebra and shapes</p></div>${sart('math',C.pink,92)}</div><div class="card dark t1"><div class="row sp"><span class="pill">Level: ${lvl().name}</span><b>${prog()}%</b></div><div style="margin-top:10px">${bar(prog(),C.lime)}</div></div>
<h2>Chapters</h2>${ch.map((c,i)=>`<div class="card ch ${c[1]==1?'done':''} ${c[1]==2?'cur':''} ${c[1]<0?'locked':''} ${i%2?'t2':'t1'}" onclick="openCh(${i},${c[1]})">${c[1]==1?ico('check',46,C.lime):c[1]<0?ico('lock',46,'#9bb'):'<div class="num">'+(i+1)+'</div>'}<div style="flex:1"><h3>${c[0]}</h3><p class="sm">${c[1]==1?'Completed!':c[1]<0?'Locked – finish chapter 2':'Current chapter'}</p></div>${c[1]==2||c[1]==0?ico('tri',38,C.yel):''}</div>`).join('')}
<h2>Activities</h2><button class="btn" ${S.lessonDone?'':'disabled'} onclick="startQuiz()">${S.lessonDone?'Start Chapter Quiz':'Quiz unlocks after the lesson'}</button></div>`},
lesson:()=>{const L=LESSON[S.lp];return`<div class="pg">${deco()}<button class="btn sm ghost" onclick="go('explore','subject')">← Chapter 2</button><h1 style="margin:12px 0 4px">Linear Equations</h1><div class="steps">${[0,1,2].map(i=>`<i class="${i<=S.lp?'on':''}"></i>`).join('')}</div>
<div class="card t1"><span class="pill p">${S.lp+1}. ${L[0]}</span><p style="margin-top:10px;font-size:17px">${L[1]}</p></div><div class="note">${ico('bulb',44,C.yel,C.lime)}<p><b>Remember:</b> ${L[2]}</p></div><div class="div"></div><div class="ex t2"><h3>Example</h3><code>${L[3]}</code></div>
<div class="row" style="margin-top:18px"><button class="btn ghost" ${S.lp?'':'disabled'} onclick="S.lp--;render()">Back</button>${S.lp<2?`<button class="btn" onclick="S.lp++;render()">Next</button>`:`<button class="btn mag" onclick="finishLesson()">${S.lessonDone?'Completed!':'I finished!'}</button>`}</div></div>`},
challenges:()=>`<div class="pg">${deco()}${head('Challenges','Earn XP and stickers',ico('bolt',60,C.yel))}<div class="card dark t1" style="overflow:hidden"><div class="row"><div style="flex:1"><div class="row sp"><h3>Daily: Math quiz</h3><span class="pill y">+50</span></div>${bar(S.daily?100:S.lessonDone?50:10,C.lime)}</div>${ico('monster',70,C.pink,C.yel)}</div><button class="btn" onclick="S.lessonDone?startQuiz():(toast('Finish the lesson first','err'),go('explore','subject'))" ${S.daily?'disabled':''}>${S.daily?'Completed!':'Go!'}</button></div><div class="card row t2">${ico('flame',56,C.pink,C.yel)}<div><h3>Keep the streak</h3><p class="sm">${S.streak}/7 days – finish today's challenge to unlock the badge.</p></div></div></div>`,
quiz:()=>{const[q,o,c,e]=QZ[S.q],ok=S.sel==c;return`<div class="pg">${deco()}<div class="row sp"><span class="pill p">Mathematics</span><b style="font-size:20px">${S.q+1}/${QZ.length}</b></div><div class="steps">${QZ.map((_,i)=>`<i class="${i<S.q||(i==S.q&&S.sub)?'on':''}"></i>`).join('')}</div><div class="row" style="align-items:flex-end">${ico('robot',72,C.tur,C.yel)}<div class="qbub" style="flex:1;margin:0"><h1>${q}</h1></div></div><div style="height:16px"></div>${o.map((t,i)=>`<button class="opt ${S.sub?(i==c?'right':i==S.sel?'wrong':''):S.sel==i?'sel':''}" ${S.sub?'disabled':''} onclick="S.sel=${i};render()"><b>${'ABCD'[i]}</b>${t}</button>`).join('')}${S.sub?`<div class="alert ${ok?'':'err'}">${ico(ok?'check':'cross',40,ok?C.lime:C.mag)}<div><b>${ok?'Yes! +20 XP':'Oops, not quite!'}</b><br><span class="sm">${e}</span></div></div><button class="btn" onclick="nextQ()">${S.q<QZ.length-1?'Next question':'See results'}</button>`:`<button class="btn" ${S.sel==null?'disabled':''} onclick="submitQ()">Check answer</button>`}</div>`},
result:()=>`<div class="pg">${deco()}<div class="mascot">${svgw(frag('burst',C.yel),200).replace('<svg','<svg style="left:10px;top:0"')}<img class="mc" src="${MASCOT.thumbs}" alt="Mascot"></div><h1 style="text-align:center;margin-top:8px">Quiz complete!</h1><p style="text-align:center;color:var(--pur);font-size:17px">${S.score==3?'Perfect! Amazing work!':'Great effort – keep going!'}</p><div class="grid" style="margin-top:18px"><div class="card stat t1" style="background:#D9FFD0"><b style="font-size:34px">${S.score}/3</b><span>Score</span></div><div class="card stat t2" style="background:#FFF4B8"><b style="font-size:34px">+${S.score*20+50}</b><span>XP earned</span></div></div><div class="card row dark">${stk(S.score==3?'star':'bolt',60,C.lime,C.yel,'#fff')}<div><h3>${S.score==3?'Perfect Score sticker!':'First Quiz sticker!'}</h3><p class="sm">Check your profile to see it.</p></div></div><button class="btn" onclick="go('progress')">See my progress</button></div>`,
progress:()=>{const pr=SUBJ.slice(0,5).map((s,i)=>[s[0],Math.round((i==0?(s[5]+S.lessons-6):s[5])/s[6]*100),s[2]]);const d=[30,45,20,60,40,70,S.daily?95:12],cl=[C.pink,C.tur,C.lime,C.yel,C.pink,C.tur,C.lime];return`<div class="pg">${deco()}${head('My Progress','Look how far you got!',ico('bars',60,C.lime,C.tur))}${hero()}<div class="grid" style="margin-top:20px"><div class="card stat t1">${ico('book',44,C.pink)}<b>${S.lessons}</b><span>Lessons done</span></div><div class="card stat t2">${ico('bolt',44,C.yel)}<b>${S.quizzes}</b><span>Quizzes done</span></div></div>
<h2>This week</h2><div class="card"><div class="chart">${d.map((h,i)=>`<div style="height:${h}%;background:${cl[i]}">${'MTWTFSS'[i]}</div>`).join('')}</div></div><h2>By subject</h2><div class="card">${pr.map(p=>`<div style="margin-bottom:10px"><div class="row sp"><h3>${p[0]}</h3><b>${p[1]}%</b></div>${bar(p[1],p[2]=='#64106E'?C.pur:p[2])}</div>`).join('')}</div><h2>Recent activity</h2>${S.acts.slice(-4).reverse().map(a=>`<div class="alert">${ico('check',30,C.lime)}<span>${a}</span></div>`).join('')}</div>`},
profile:()=>`<div class="pg">${deco()}<div style="text-align:center"><div class="ph" style="width:170px;height:170px;margin:0 auto">${svgw(frag('burst',C.pink),190).replace('<svg','<svg style="inset:-10px;width:190px;height:190px"')}<img class="mc" style="inset:18px;width:134px;height:134px" src="${MASCOT.lab}" alt="Mascot"></div><h1>Yotsuba</h1><p>Grade 8 · <b>${lvl().name}</b></p><div style="margin-top:8px"><span class="pill y">${S.xp} XP</span> <span class="pill">${S.streak} day streak</span></div></div>
<h2>My stickers</h2><div class="grid" style="grid-template-columns:repeat(3,1fr);gap:4px">${BADGES.map(b=>`<div class="card badge ${S.badges.includes(b[0])?'':'lock'}">${stk(b[1],86,b[3],C.yel,'#fff')}<br>${b[2]}</div>`).join('')}</div><div class="card row sp t1"><h3>Demo settings</h3><button class="btn sm mag" onclick="location.reload()">Reset demo</button></div></div>`
};
function openCh(i,s){if(s<0)return toast('Finish chapter 2 first','err');S.lp=0;go('explore','lesson')}
function finishLesson(){if(!S.lessonDone){S.lessonDone=true;S.lessons++;S.acts.push('Completed "Aljabar Dasar"');gain(30,'Lesson completed! Great job!');unlock('lesson')}render()}
function startQuiz(){S.q=0;S.sel=null;S.sub=false;S.score=0;go('challenges','quiz')}
function submitQ(){S.sub=true;if(S.sel==QZ[S.q][2]){S.score++;gain(20)}render()}
function nextQ(){if(S.q<QZ.length-1){S.q++;S.sel=null;S.sub=false;return render()}
S.quizzes++;S.acts.push('Quiz Aljabar: '+S.score+'/3');gain(50,'Quiz completed!');unlock('quiz');if(S.score==3)unlock('perfect');if(!S.daily){S.daily=true;S.streak=7;unlock('streak')}go('challenges','result')}
const NAV=[['home','home','Home'],['explore','compass','Explore'],['challenges','bolt','Challenges'],['progress','bars','Progress'],['profile','face','Profile']];
function render(){$('#screen').innerHTML=V[S.v]();$('#screen').scrollTop=0;$('#nav').innerHTML=NAV.map(n=>`<button class="${S.tab==n[0]?'on':''}" onclick="go('${n[0]}')">${ico(n[1],30,C.pink,C.tur)}${n[2]}</button>`).join('')}
render();
